<?php
namespace TNG_OS\Modules\Entities;
use TNG_OS\Core\Container; use TNG_OS\Core\Module_Interface;
if (!defined('ABSPATH')) exit;
final class Recommendation_Studio implements Module_Interface {
 private Container $container;
 public function id():string{return'recommendation_studio';}
 public function register(Container $container):void{$this->container=$container;$container->set('recommendation_studio',$this);add_action('admin_menu',[$this,'menu'],28);add_action('admin_post_tng_save_recommendation_weights',[$this,'save_weights']);add_action('admin_post_tng_reset_recommendation_weights',[$this,'reset_weights']);}
 public function boot(Container $container):void{}
 public function menu():void{add_submenu_page('tn-game-os','Recommendation Studio','Recommendation Studio','manage_options','tng-recommendation-studio',[$this,'page']);}
 public function save_weights():void{if(!current_user_can('manage_options'))wp_die('Unauthorized');check_admin_referer('tng_save_recommendation_weights');if($e=$this->engine())$e->save_relationship_weights((array)($_POST['weights']??[]));wp_safe_redirect(add_query_arg(['page'=>'tng-recommendation-studio','updated'=>'1'],admin_url('admin.php')));exit;}
 public function reset_weights():void{if(!current_user_can('manage_options'))wp_die('Unauthorized');check_admin_referer('tng_reset_recommendation_weights');if($e=$this->engine())$e->reset_relationship_weights();wp_safe_redirect(add_query_arg(['page'=>'tng-recommendation-studio','reset'=>'1'],admin_url('admin.php')));exit;}
 private function confidence(int $score):array{if($score>=125)return['Excellent match','excellent',min(100,(int)round($score/1.5))];if($score>=90)return['Strong match','strong',min(95,(int)round($score/1.5))];if($score>=60)return['Good match','good',min(85,(int)round($score/1.5))];return['Exploratory match','explore',max(20,min(70,(int)round($score/1.5)))];}
 private function clean_weights(array $input,array $defaults):array{$out=[];foreach($defaults as $type=>$value)$out[$type]=max(0,min(500,absint($input[$type]??$value)));return$out;}
 public function page():void{
  if(!current_user_can('manage_options'))return;$engine=$this->engine();if(!$engine){echo'<div class="wrap"><h1>Recommendation Studio</h1><div class="notice notice-error"><p>Recommendation Engine is unavailable.</p></div></div>';return;}
  $entities=$engine->entities();$selected=isset($_GET['entity'])?sanitize_text_field(wp_unslash($_GET['entity'])):'';if($selected===''&&$entities)$selected=(string)array_key_first($entities);$depth=max(1,min(3,absint($_GET['depth']??2)));$limit=max(1,min(30,absint($_GET['limit']??12)));$types=isset($_GET['types'])?array_values(array_filter(array_map('sanitize_key',explode(',',sanitize_text_field(wp_unslash($_GET['types'])))))):[];
  $weights=$engine->relationship_weights();$baseline=$selected!==''?$engine->recommend($selected,['depth'=>$depth,'limit'=>$limit,'types'=>$types,'require_url'=>false]):[];$simulating=isset($_GET['simulate']);$preview=$this->clean_weights((array)($_GET['preview_weights']??[]),$weights);$results=$baseline;
  if($simulating&&$selected!==''){$filter=static fn(array $current):array=>array_merge($current,$preview);add_filter('tng_recommendation_relationship_weights',$filter,999);$results=$engine->recommend($selected,['depth'=>$depth,'limit'=>$limit,'types'=>$types,'require_url'=>false]);remove_filter('tng_recommendation_relationship_weights',$filter,999);}
  $base_map=[];foreach($baseline as $i=>$item)$base_map[$item['id']]=['rank'=>$i+1,'score'=>(int)$item['score']];$max_weight=max(1,max($simulating?$preview:$weights));?>
 <div class="wrap tng-rec-studio"><style>
 .tng-rec-studio{max-width:1500px}.tng-rs-hero{background:linear-gradient(135deg,#162747,#243c67);color:#fff;border-radius:18px;padding:28px 30px;margin:18px 0}.tng-rs-hero h1{color:#fff;margin:0 0 6px;font-size:30px}.tng-rs-toolbar,.tng-rs-card{background:#fff;border:1px solid #dcdcde;border-radius:14px;padding:18px}.tng-rs-toolbar form{display:flex;gap:10px;align-items:end;flex-wrap:wrap}.tng-rs-toolbar label{display:grid;gap:5px;font-weight:600}.tng-rs-toolbar select{min-width:330px}.tng-rs-layout{display:grid;grid-template-columns:minmax(0,1fr) 390px;gap:18px;margin-top:18px}.tng-rs-results{display:grid;gap:14px}.tng-rs-result{background:#fff;border:1px solid #dcdcde;border-radius:14px;padding:18px}.tng-rs-result-head{display:flex;justify-content:space-between;gap:16px}.tng-rs-score{display:inline-flex;align-items:center;justify-content:center;min-width:64px;height:64px;border-radius:50%;background:#162747;color:#fff;font-size:22px;font-weight:800}.tng-rs-confidence{font-size:12px;font-weight:700;margin-top:7px;text-align:center}.excellent{color:#067647}.strong{color:#175cd3}.good{color:#b54708}.explore{color:#667085}.tng-rs-meter{height:8px;background:#eef2f6;border-radius:999px;overflow:hidden;margin:12px 0}.tng-rs-meter span{display:block;height:100%;background:#4f46e5}.tng-rs-badges{display:flex;gap:6px;flex-wrap:wrap;margin:10px 0}.tng-rs-badge,.tng-rs-delta{background:#eef2ff;border-radius:999px;padding:5px 10px;font-size:12px}.tng-rs-delta.up{background:#ecfdf3;color:#067647}.tng-rs-delta.down{background:#fef3f2;color:#b42318}.tng-rs-breakdown{display:grid;gap:8px;margin-top:14px}.tng-rs-factor{display:grid;grid-template-columns:minmax(150px,1fr) 3fr 55px;gap:10px;align-items:center}.tng-rs-factor-bar,.tng-rs-weight-bar{height:8px;background:#eef2f6;border-radius:999px;overflow:hidden}.tng-rs-factor-bar span,.tng-rs-weight-bar span{display:block;height:100%;background:#4f46e5}.negative .tng-rs-factor-bar span{background:#d92d20}.tng-rs-points{text-align:right;font-weight:800}.tng-rs-path{display:flex;gap:7px;align-items:center;flex-wrap:wrap;margin-top:16px;padding-top:14px;border-top:1px solid #eef0f3}.tng-rs-node{background:#f6f7f7;border-radius:8px;padding:6px 9px;font-weight:600}.tng-rs-edge{color:#646970;font-size:12px}.tng-rs-weight-row{display:grid;grid-template-columns:1fr 90px;gap:10px;align-items:center;margin:11px 0}.tng-rs-weight-name{display:flex;justify-content:space-between}.tng-rs-weight-row input{width:90px}.tng-rs-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:16px}.tng-rs-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-top:14px}.tng-rs-stat{background:#f8fafc;border-radius:12px;padding:14px}.tng-rs-stat strong{display:block;font-size:24px;color:#162747}.tng-rs-sim{border:2px solid #7c3aed}.tng-rs-sim-label{display:inline-block;background:#7c3aed;color:#fff;border-radius:999px;padding:5px 10px;font-size:12px;font-weight:700;margin-bottom:10px}@media(max-width:1000px){.tng-rs-layout{grid-template-columns:1fr}.tng-rs-toolbar select{min-width:240px}}@media(max-width:700px){.tng-rs-summary{grid-template-columns:1fr 1fr}.tng-rs-factor{grid-template-columns:1fr 55px}.tng-rs-factor-bar{grid-column:1/-1}}
 </style>
 <div class="tng-rs-hero"><p style="text-transform:uppercase;letter-spacing:.12em;margin:0 0 8px;color:#f6bd3b;font-weight:700">TN Platform · Recommendation Intelligence</p><h1>Recommendation Studio</h1><p>Inspect rankings, tune the graph, and safely test changes before they go live.</p></div>
 <?php if(isset($_GET['updated'])):?><div class="notice notice-success inline"><p>Recommendation weights saved.</p></div><?php endif;?>
 <div class="tng-rs-toolbar"><form method="get"><input type="hidden" name="page" value="tng-recommendation-studio"><label>Analyze entity<select name="entity"><?php foreach($entities as $entity):?><option value="<?php echo esc_attr($entity['id']);?>" <?php selected($selected,$entity['id']);?>><?php echo esc_html($entity['title'].' · '.$entity['type']);?></option><?php endforeach;?></select></label><label>Depth<select name="depth"><option value="1" <?php selected($depth,1);?>>1 hop</option><option value="2" <?php selected($depth,2);?>>2 hops</option><option value="3" <?php selected($depth,3);?>>3 hops</option></select></label><label>Limit<input type="number" min="1" max="30" name="limit" value="<?php echo esc_attr((string)$limit);?>"></label><label>Types<input type="text" name="types" value="<?php echo esc_attr(implode(',',$types));?>" placeholder="restaurant,trail,hotel"></label><button class="button button-primary">Analyze</button><a class="button" href="<?php echo esc_url(admin_url('admin.php?page=tng-graph-explorer&entity='.rawurlencode($selected)));?>">Open Graph Explorer</a></form></div>
 <div class="tng-rs-summary"><div class="tng-rs-stat"><span>Recommendations</span><strong><?php echo esc_html((string)count($results));?></strong></div><div class="tng-rs-stat"><span>Top score</span><strong><?php echo esc_html((string)($results[0]['score']??0));?></strong></div><div class="tng-rs-stat"><span>Graph depth</span><strong><?php echo esc_html((string)$depth);?> hops</strong></div><div class="tng-rs-stat"><span>Mode</span><strong><?php echo $simulating?'What-if':'Live';?></strong></div></div>
 <div class="tng-rs-layout"><main class="tng-rs-results"><?php if($simulating):?><div class="tng-rs-card tng-rs-sim"><span class="tng-rs-sim-label">WHAT-IF PREVIEW</span><h2 style="margin:0">Temporary rankings</h2><p>Nothing has been saved. Rank and score changes are compared with the live configuration.</p></div><?php endif;?><?php if(!$results):?><div class="tng-rs-card"><p>No recommendations were found.</p></div><?php endif;?>
 <?php foreach($results as $index=>$item):$confidence=$this->confidence((int)$item['score']);$factor_max=max(1,max(array_map(static fn($f)=>abs((int)$f['points']),(array)$item['breakdown'])));$old=$base_map[$item['id']]??null;$rank_delta=$old?$old['rank']-($index+1):0;$score_delta=$old?(int)$item['score']-$old['score']:0;?><article class="tng-rs-result"><div class="tng-rs-result-head"><div><small>#<?php echo esc_html((string)($index+1));?> · <?php echo esc_html($item['type']);?></small><h2 style="margin:4px 0"><?php echo esc_html($item['title']);?></h2><code><?php echo esc_html($item['id']);?></code><div class="tng-rs-badges"><?php if($simulating&&$rank_delta):?><span class="tng-rs-delta <?php echo $rank_delta>0?'up':'down';?>"><?php echo $rank_delta>0?'▲ Up ':'▼ Down '; echo esc_html((string)abs($rank_delta));?> rank<?php echo abs($rank_delta)===1?'':'s';?></span><?php endif;?><?php if($simulating&&$score_delta):?><span class="tng-rs-delta <?php echo $score_delta>0?'up':'down';?>"><?php echo $score_delta>0?'+':''; echo esc_html((string)$score_delta);?> points</span><?php endif;?></div></div><div><div class="tng-rs-score"><?php echo esc_html((string)$item['score']);?></div><div class="tng-rs-confidence <?php echo esc_attr($confidence[1]);?>"><?php echo esc_html($confidence[0]);?></div></div></div><div class="tng-rs-meter"><span style="width:<?php echo esc_attr((string)$confidence[2]);?>%"></span></div><div class="tng-rs-badges"><?php foreach((array)$item['reasons'] as $reason):?><span class="tng-rs-badge"><?php echo esc_html($reason);?></span><?php endforeach;?></div><div class="tng-rs-breakdown"><?php foreach((array)$item['breakdown'] as $factor):$points=(int)$factor['points'];?><div class="tng-rs-factor <?php echo $points<0?'negative':'';?>"><span><?php echo esc_html((string)$factor['label']);?></span><div class="tng-rs-factor-bar"><span style="width:<?php echo esc_attr((string)round(abs($points)/$factor_max*100));?>%"></span></div><span class="tng-rs-points"><?php echo $points>0?'+':''; echo esc_html((string)$points);?></span></div><?php endforeach;?></div><div class="tng-rs-path"><span class="tng-rs-node"><?php echo esc_html($entities[$selected]['title']??$selected);?></span><?php foreach((array)$item['path'] as $edge):?><span class="tng-rs-edge">→ <?php echo esc_html((string)$edge['type']);?> →</span><span class="tng-rs-node"><?php echo esc_html($entities[$edge['to_entity_id']]['title']??$edge['to_entity_id']);?></span><?php endforeach;?></div></article><?php endforeach;?></main>
 <aside class="tng-rs-card"><h2 style="margin-top:0">What-if simulator</h2><p>Change weights and preview the result without affecting the public site.</p><form method="get"><input type="hidden" name="page" value="tng-recommendation-studio"><input type="hidden" name="entity" value="<?php echo esc_attr($selected);?>"><input type="hidden" name="depth" value="<?php echo esc_attr((string)$depth);?>"><input type="hidden" name="limit" value="<?php echo esc_attr((string)$limit);?>"><input type="hidden" name="types" value="<?php echo esc_attr(implode(',',$types));?>"><input type="hidden" name="simulate" value="1"><?php foreach(($simulating?$preview:$weights) as $type=>$weight):?><div class="tng-rs-weight-row"><div><div class="tng-rs-weight-name"><code><?php echo esc_html($type);?></code><strong><?php echo esc_html((string)$weight);?></strong></div><div class="tng-rs-weight-bar"><span style="width:<?php echo esc_attr((string)round($weight/$max_weight*100));?>%"></span></div></div><input type="number" min="0" max="500" name="preview_weights[<?php echo esc_attr($type);?>]" value="<?php echo esc_attr((string)$weight);?>"></div><?php endforeach;?><div class="tng-rs-actions"><button class="button button-primary">Preview changes</button><a class="button" href="<?php echo esc_url(add_query_arg(['page'=>'tng-recommendation-studio','entity'=>$selected,'depth'=>$depth,'limit'=>$limit,'types'=>implode(',',$types)],admin_url('admin.php')));?>">Discard preview</a></div></form><?php if($simulating):?><hr><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="tng_save_recommendation_weights"><?php wp_nonce_field('tng_save_recommendation_weights');foreach($preview as $type=>$weight):?><input type="hidden" name="weights[<?php echo esc_attr($type);?>]" value="<?php echo esc_attr((string)$weight);?>"><?php endforeach;?><button class="button button-primary" style="width:100%">Apply preview to live site</button></form><?php endif;?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>" style="margin-top:10px"><input type="hidden" name="action" value="tng_reset_recommendation_weights"><?php wp_nonce_field('tng_reset_recommendation_weights');?><button class="button">Reset defaults</button></form></aside></div></div><?php }
 private function engine():?Recommendation_Engine{$e=$this->container->get('recommendation_engine');return$e instanceof Recommendation_Engine?$e:null;}
}